*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101121;color:#f4f3fa;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#111322}#game{display:block;width:100%;height:100%;outline:none;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(10,12,24,.6),transparent 20%,transparent 66%,rgba(9,10,20,.62)),radial-gradient(ellipse at center,transparent 46%,rgba(7,8,19,.32) 100%)}.topbar{position:absolute;top:24px;left:34px;right:34px;height:44px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.brand{display:flex;align-items:center;gap:11px;text-shadow:0 2px 12px #111}.brand-mark{font-size:30px;color:#d4beff}.brand b{font:700 15px 'Space Grotesk';letter-spacing:.22em;display:block}.brand small{font-size:8px;letter-spacing:.25em;color:#d3d0e0;opacity:.72}.region{display:flex;align-items:center;gap:13px;font-size:10px;font-weight:600;letter-spacing:.22em;text-shadow:0 2px 8px #111}.region-line{width:26px;height:1px;background:#d9ceff;opacity:.55}.icon-button{width:40px;height:40px;border:1px solid #ffffff3b;background:#14132266;border-radius:50%;font-size:25px;pointer-events:auto;cursor:pointer;backdrop-filter:blur(8px)}.quest-card{position:absolute;top:104px;left:36px;width:280px;padding:17px 19px 16px;background:linear-gradient(110deg,rgba(15,17,31,.77),rgba(22,20,36,.48));border-left:2px solid #b99cff;backdrop-filter:blur(9px);box-shadow:0 10px 35px #09091625}.eyebrow{color:#d5c7fc;font-size:9px;letter-spacing:.19em;font-weight:700;display:flex;gap:8px;align-items:center}.live-dot{width:5px;height:5px;border-radius:50%;background:#c9aaff;box-shadow:0 0 8px #bd97ff}.quest-card h1{font:600 16px 'Space Grotesk';margin:12px 0 11px}.quest-step{font-size:11px;color:#d9d6e5;display:flex;align-items:center;gap:8px}.step-icon{color:#d0adff;font-size:16px}.quest-progress{height:2px;background:#ffffff25;margin-top:12px}.quest-progress span{display:block;height:100%;width:0;background:#c8a9ff;transition:width .5s}.quest-count{font-size:9px;color:#a8a4b9;text-align:right;margin-top:5px}.player-card{position:absolute;left:36px;bottom:33px;width:292px;display:flex;align-items:center;gap:13px;padding:13px 15px;background:linear-gradient(100deg,rgba(15,16,30,.82),rgba(22,20,37,.58));border:1px solid #ffffff19;backdrop-filter:blur(12px);box-shadow:0 8px 30px #09091630}.portrait{width:45px;height:45px;border:1px solid #d5bdff80;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,#a989d988,#38304b 70%);font-size:27px;color:#fff4d8;position:relative;flex:none}.portrait i{position:absolute;width:8px;height:8px;border-radius:50%;background:#97f2e6;right:0;bottom:0;box-shadow:0 0 10px #5fe5d6}.player-info{width:100%}.player-title{display:flex;justify-content:space-between;align-items:center;font:700 11px 'Space Grotesk';letter-spacing:.12em;margin-bottom:8px}.player-title span{font:500 8px 'DM Sans';letter-spacing:.14em;color:#aaa5bc}.player-title strong{color:#ded0ff;font-size:10px;margin-left:4px}.bar-label{display:flex;justify-content:space-between;color:#d4d0df;font-size:8px;letter-spacing:.12em;margin:4px 0}.bar{height:5px;background:#ffffff20;border-radius:6px;overflow:hidden}.bar i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#f36c94,#ffb1b8);border-radius:8px;transition:width .2s}.energy-label{margin-top:7px}.energy{height:3px}.energy i{background:linear-gradient(90deg,#8c68ff,#b9a2ff);width:100%}.combat-feed{position:absolute;bottom:197px;left:37px;display:flex;flex-direction:column;gap:5px;pointer-events:none}.combat-feed div{font-size:10px;color:#f0d7ff;text-shadow:0 2px 4px #171126;animation:feed-in .25s ease-out}.combat-feed .damage{color:#ffd39e}@keyframes feed-in{from{transform:translateX(-10px);opacity:0}to{transform:none;opacity:1}}.boss-bar{position:absolute;top:40px;left:50%;transform:translateX(-50%);width:min(440px,54vw);text-align:center}.boss-heading{display:flex;flex-direction:column;gap:5px;font-size:9px;letter-spacing:.18em;color:#ffb6ce}.boss-heading b{font:700 12px 'Space Grotesk';letter-spacing:.15em;color:#fff}.bar.boss{margin-top:9px;height:6px;background:#fff2}.bar.boss i{background:linear-gradient(90deg,#d34078,#ff9bb2);transition:width .2s}.hidden{display:none!important}.interact-prompt{position:absolute;top:57%;left:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:10px;padding:10px 16px;background:#171426c9;border:1px solid #c8a9ff75;box-shadow:0 4px 25px #0e0a1e80;font-size:10px;letter-spacing:.14em;animation:pulse 1.5s infinite;pointer-events:none}.interact-prompt span{width:22px;height:22px;display:grid;place-items:center;background:#c5a5ff;color:#171324;border-radius:4px;font-size:12px;font-weight:700}.interact-prompt{visibility:hidden}@keyframes pulse{50%{box-shadow:0 0 25px #b58aff55}}.controls-hint{position:absolute;right:35px;bottom:38px;display:flex;align-items:center;gap:8px;color:#d9d5e4;font-size:9px;text-shadow:0 2px 5px #111}.controls-hint span{padding:5px 7px;border:1px solid #ffffff45;background:#1514248a;border-radius:4px;font-size:8px;font-weight:700}.controls-hint i{height:3px;width:3px;border-radius:50%;background:#c6a9ff;margin:0 4px}.minimap-wrap{position:absolute;top:95px;right:34px;width:145px;height:170px;text-align:center}.minimap-wrap canvas{width:124px;height:124px;border-radius:50%;border:1px solid #e8dbff9c;box-shadow:0 0 0 5px #1815276b,0 6px 22px #08091870;background:#202237aa}.map-label{font-size:8px;letter-spacing:.18em;text-shadow:0 1px 5px #000;margin-top:10px}.skillbar{position:absolute;bottom:27px;right:35px;display:flex;align-items:flex-end;gap:16px}.skill-group{position:relative;display:grid;justify-items:center;gap:4px;min-width:45px}.skill-key{position:absolute;right:-2px;top:-7px;z-index:2;min-width:18px;height:17px;padding:0 4px;display:grid;place-items:center;border:1px solid #ffffff86;border-radius:4px;background:#161525;color:#fff;font-size:8px;font-weight:700}.skill-icon{width:40px;height:40px;border:1px solid #ffffff75;border-radius:50%;display:grid;place-items:center;background:linear-gradient(140deg,#51466fbb,#171625ed);box-shadow:0 4px 15px #08081588;font-size:20px}.basic{color:#fff1d2}.skill-q{color:#d9c4ff;font-size:24px;border-color:#c5adff9c}.skill-e{color:#fff3d4;font-size:24px;border-color:#f8d793;background:linear-gradient(140deg,#8b552f,#392539);box-shadow:0 0 15px #ffcf7955}.dodge{color:#d6faff}.skill-name{font-size:7px;letter-spacing:.1em;color:#e3dfeb;text-shadow:0 1px 4px #000}.ultimate .skill-icon{width:48px;height:48px}.ultimate-charge{height:2px;width:42px;background:#ffffff40}.ultimate-charge i{display:block;height:100%;width:100%;background:#ffdf91;box-shadow:0 0 7px #ffdd8a}.cooldown{position:absolute;inset:0;border-radius:50%;background:#1119;transform:scaleY(0);transform-origin:bottom;pointer-events:none}.toast{position:absolute;left:50%;top:30%;transform:translate(-50%,-10px);padding:11px 18px;background:#171426d9;border:1px solid #ddc9ff70;color:#f0e9ff;font:600 11px 'Space Grotesk';letter-spacing:.09em;opacity:0;transition:.3s;pointer-events:none;text-align:center;max-width:90vw}.toast.show{opacity:1;transform:translate(-50%,0)}.damage-flash{position:absolute;inset:0;pointer-events:none;border:0 solid #ff4d7090;transition:border-width .1s}.damage-flash.hit{border-width:12px;box-shadow:inset 0 0 70px #ff315528}.start-screen,.end-screen{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(9,10,21,.89),rgba(10,11,22,.55) 54%,rgba(10,11,22,.22)),linear-gradient(0deg,#10112166,transparent 50%);z-index:5}.start-content{position:absolute;left:clamp(35px,10vw,170px);top:50%;transform:translateY(-46%);max-width:490px}.start-kicker{font-size:10px;font-weight:600;letter-spacing:.22em;color:#d4c1ff;margin-bottom:20px}.start-kicker span{font-size:15px;margin-right:8px}.start-content h2,.end-screen h2{font:600 clamp(45px,6.6vw,82px)/.93 'Space Grotesk';letter-spacing:.005em;margin:0;text-shadow:0 5px 25px #0c0b19}.start-content h2 span{color:#d5b9ff}.start-content h2 em,.end-screen h2 em{font-size:.51em;font-style:normal;letter-spacing:.32em;color:#e5dcf4}.start-content p{font-size:13px;line-height:1.75;color:#cbc7d7;margin:24px 0 25px}.start-content button,.end-screen button{width:235px;height:47px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;border:1px solid #dfcfff;background:linear-gradient(100deg,#b99bf4,#8465bb);color:#171324;font-size:10px;font-weight:700;letter-spacing:.13em;cursor:pointer;box-shadow:0 4px 25px #b48aff38;transition:.2s}.start-content button:hover,.end-screen button:hover{filter:brightness(1.15);transform:translateY(-2px)}.start-content button b{font-size:19px}.start-controls{font-size:9px;color:#c8c3d4;margin-top:23px;letter-spacing:.04em}.start-controls i{font-style:normal;color:#a39bac}.start-stars{position:absolute;inset:0;pointer-events:none;background-image:radial-gradient(1px 1px at 72% 24%,#fff 50%,transparent 60%),radial-gradient(1px 1px at 83% 38%,#e0cfff 50%,transparent 60%),radial-gradient(1px 1px at 67% 67%,#fff 50%,transparent 60%),radial-gradient(1px 1px at 93% 78%,#fff 50%,transparent 60%),radial-gradient(2px 2px at 80% 16%,#c9bbff 50%,transparent 60%);opacity:.8}.start-footer{position:absolute;bottom:25px;left:clamp(35px,10vw,170px);font-size:8px;letter-spacing:.2em;color:#aaa5b7}.start-footer span{color:#d0b6ff;margin-right:7px}.end-screen{z-index:4;background:rgba(10,10,24,.84);text-align:center}.end-kicker{color:#dfcbff;font-size:10px;letter-spacing:.3em}.end-screen h2{font-size:60px;margin:20px 0}.end-screen h2 em{font-size:.65em}.end-screen p{font-size:13px;color:#c9c4d2;margin-bottom:30px}.end-screen button{margin:auto;justify-content:center;width:260px}.mobile-controls{display:none;position:absolute;inset:0;pointer-events:none}.joystick{position:absolute;left:25px;bottom:34px;width:110px;height:110px;border:1px solid #ffffff43;background:#17152777;border-radius:50%;pointer-events:auto;touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;width:42px;height:42px;border-radius:50%;transform:translate(-50%,-50%);background:#d9c5ff88;border:1px solid #f3eaffaa}.mobile-actions{position:absolute;right:22px;bottom:31px;display:flex;align-items:flex-end;gap:9px;pointer-events:auto}.mobile-actions button{width:45px;height:45px;border-radius:50%;border:1px solid #e6d9ff99;background:#241d36cc;color:white;font-size:20px;box-shadow:0 2px 12px #0008;touch-action:none}.mobile-actions button[data-action=ult]{width:52px;height:52px;background:#624528dd;color:#ffe0a2}.mobile-actions button[data-action=attack]{width:55px;height:55px}.mobile-actions button[data-action=dodge]{width:39px;height:39px;font-size:16px}.map-open{position:absolute;inset:8%;z-index:3;border:1px solid #d7c6ff;background:#111223eF;border-radius:4px;display:grid;place-items:center;backdrop-filter:blur(12px);color:#eee;font:600 13px 'Space Grotesk';letter-spacing:.15em}.map-open canvas{width:min(60vw,430px);height:min(60vw,430px);border:1px solid #a68bd6;border-radius:50%}
