import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x8586a9);scene.fog=new THREE.FogExp2(0x8989a6,.0125);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,240);camera.position.set(0,5,9);
const clock=new THREE.Clock();
const hemi=new THREE.HemisphereLight(0xc9d2ff,0x42384e,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffddb5,3.1);sun.position.set(-20,32,-14);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;sun.shadow.bias=-.0003;scene.add(sun);
const rim=new THREE.DirectionalLight(0x96aaff,1.5);rim.position.set(15,9,24);scene.add(rim);
const mat=(color,roughness=.8,metalness=0,emissive=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:emissive?1.2:0});
const groundMat=mat(0x777080),stoneMat=mat(0x554e67),lightStone=mat(0xaaa0ac),darkMat=mat(0x242436),goldMat=mat(0xd0a76a,.38,.65),tealMat=mat(0x69e4dc,.26,.25,0x36b8b2),purpleMat=mat(0x9875ff,.23,.15,0x6a45dc),pinkMat=mat(0xff6ba5,.25,.2,0xd62d75),leafMat=mat(0x526568),leaf2Mat=mat(0x756278);
const world=new THREE.Group();scene.add(world);
const groundGeo=new THREE.PlaneGeometry(190,190,100,100);groundGeo.rotateX(-Math.PI/2);
const pos=groundGeo.attributes.position;for(let i=0;i<pos.count;i++){let x=pos.getX(i),z=pos.getZ(i);let h=Math.sin(x*.15+1.3)*.65+Math.cos(z*.13)*.55+Math.sin((x+z)*.075)*1.1;h+=Math.max(0,Math.sin(x*.055)*Math.cos(z*.045))*2.2;pos.setY(i,h)}groundGeo.computeVertexNormals();
const ground=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({color:0x77717c,roughness:1,vertexColors:false}));ground.receiveShadow=true;world.add(ground);
// Broken stone paths, ridges and ruins
const rng=(()=>{let s=8721;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)})();
function groundY(x,z){return Math.sin(x*.15+1.3)*.65+Math.cos(z*.13)*.55+Math.sin((x+z)*.075)*1.1+Math.max(0,Math.sin(x*.055)*Math.cos(z*.045))*2.2}
function addMesh(parent,geometry,material,x,y,z,sx=1,sy=1,sz=1,rx=0,ry=0,rz=0){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
const cubeGeo=new THREE.BoxGeometry(1,1,1),cylGeo=new THREE.CylinderGeometry(.5,.62,1,8),icoGeo=new THREE.IcosahedronGeometry(1,0);
for(let i=0;i<115;i++){let x=(rng()-.5)*95,z=(rng()-.5)*95;if(Math.hypot(x,z)<13)continue;let y=groundY(x,z);let s=.5+rng()*2.2;let rock=addMesh(world,icoGeo,i%5===0?lightStone:stoneMat,x,y+s*.28,z,s,s*(.45+rng()*.55),s*.8,rng()*.3,rng()*3,rng()*.3);rock.castShadow=true}
// Weathered giant trees
for(let i=0;i<46;i++){let a=rng()*Math.PI*2,r=14+rng()*49,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<17)continue;let y=groundY(x,z),h=2.6+rng()*4;const trunk=addMesh(world,new THREE.CylinderGeometry(.18,.38,h,7),i%3?stoneMat:darkMat,x,y+h/2,z,.75+rng()*.7,1,.75+rng()*.6,0,rng()*6,.1);trunk.castShadow=true;for(let j=0;j<3;j++){let crown=addMesh(world,icoGeo,j%2?leafMat:leaf2Mat,x+(rng()-.5)*1.5,y+h*.68+j*.52,z+(rng()-.5)*1.5,1.2+rng()*.8,1.5+rng(),1.2+rng()*.8);crown.castShadow=true}}
// distant ridge silhouettes
for(let i=0;i<35;i++){let x=-95+i*5.7,z=-67-(rng()*19),h=8+rng()*14;addMesh(world,new THREE.ConeGeometry(5+rng()*8,h,5),i%3?mat(0x5b586f):mat(0x666279),x,groundY(x,z)+h*.28,z,1,1,1,0,rng()*2,0)}
// Embedded starlight crystals
const crystalGeo=new THREE.OctahedronGeometry(1,0);for(let i=0;i<66;i++){let a=rng()*Math.PI*2,r=8+rng()*48,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<10)continue;let y=groundY(x,z);let c=addMesh(world,crystalGeo,i%4===0?tealMat:purpleMat,x,y+.55,z,.2+rng()*.45,.45+rng()*1.25,.25+rng()*.4,0,rng()*2,.12);c.rotation.x=.1;}
// Celestial bodies, stars and floating motes
const moonMat=new THREE.MeshBasicMaterial({color:0xe6d7f0});const moon=addMesh(scene,new THREE.SphereGeometry(5,32,24),moonMat,34,32,-90);moon.material.transparent=true;moon.material.opacity=.8;
const starGeo=new THREE.BufferGeometry(),starPositions=[];for(let i=0;i<700;i++){starPositions.push((rng()-.5)*180,20+rng()*80,(rng()-.5)*180)}starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xe9e2ff,size:.16,transparent:true,opacity:.8})));
const water=new THREE.Mesh(new THREE.CircleGeometry(14,48),new THREE.MeshStandardMaterial({color:0x505878,roughness:.2,metalness:.3,transparent:true,opacity:.62,emissive:0x101a3c,emissiveIntensity:.7}));water.rotation.x=-Math.PI/2;water.position.set(-27,groundY(-27,-13)+.03,-13);world.add(water);
const water2=water.clone();water2.position.set(30,groundY(30,23)+.03,23);water2.scale.setScalar(.68);world.add(water2);
// Ancient broken arches around central plateau
for(let k=0;k<8;k++){let a=k*Math.PI/4,x=Math.cos(a)*11,z=Math.sin(a)*11,y=groundY(x,z);addMesh(world,cylGeo,lightStone,x,y+1.6,z,.43,3.2,.43,0,0,rng()*.2);addMesh(world,cubeGeo,goldMat,x,y+3.3,z,.72,.18,.72,0,a,0);addMesh(world,cubeGeo,stoneMat,x+Math.cos(a+.35)*.6,y+2.5,z+Math.sin(a+.35)*.6,.5,.5,.5,rng()*.2,a,0)}
// Main character, stylized starfarer
const player=new THREE.Group();world.add(player);player.position.set(0,groundY(0,0),0);
const bodyMat=mat(0xddd8ee,.46,.12),clothMat=mat(0x463d63,.66,.05),skinMat=mat(0xf1c6b7,.58),hairMat=mat(0x242437,.43),glowMat=mat(0x91f5ed,.24,.1,0x48ded4);
const body=addMesh(player,new THREE.CapsuleGeometry(.34,.72,5,10),bodyMat,0,1.2,0);body.castShadow=true;
addMesh(player,new THREE.SphereGeometry(.27,16,12),skinMat,0,1.91,0,1,.98,.92);
addMesh(player,new THREE.SphereGeometry(.29,16,12),hairMat,0,2.04,-.055,1,.57,1.05);
addMesh(player,new THREE.ConeGeometry(.15,.43,8),hairMat,-.19,1.97,-.12,.7,1,.7,0,0,.4);
addMesh(player,new THREE.ConeGeometry(.16,.42,8),hairMat,.17,1.98,-.1,.7,1,.7,0,0,-.35);
addMesh(player,new THREE.BoxGeometry(.8,.22,.46),clothMat,0,1.38,0,1,1,1,0,0,0);
addMesh(player,new THREE.BoxGeometry(.88,.16,.5),goldMat,0,1.1,0);
addMesh(player,new THREE.CylinderGeometry(.095,.12,.64,9),bodyMat,-.46,1.17,0,.8,1,1,0,0,-.14);addMesh(player,new THREE.CylinderGeometry(.095,.12,.64,9),bodyMat,.46,1.17,0,.8,1,1,0,0,.14);
addMesh(player,new THREE.CylinderGeometry(.14,.16,.72,8),darkMat,-.18,.48,0);addMesh(player,new THREE.CylinderGeometry(.14,.16,.72,8),darkMat,.18,.48,0);
addMesh(player,new THREE.BoxGeometry(.3,.16,.42),goldMat,-.18,.13,.06);addMesh(player,new THREE.BoxGeometry(.3,.16,.42),goldMat,.18,.13,.06);
const sword=new THREE.Group();player.add(sword);sword.position.set(.56,1.15,.05);sword.rotation.z=-.38;
