function dodge(){if(!started||dodgeCooldown>0)return;dodgeCooldown=1.1;dodgeTime=.28;invuln=.48;const dir=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));player.position.addScaledVector(dir,2.7);burst(player.position.x,player.position.y+.7,player.position.z,0x8beae1,12)}
function activateBeacon(b){if(b.active)return;b.active=true;b.crystal.material=tealMat;b.ring.material=tealMat;b.beam.material.color.set(0x84f5dc);b.beam.material.opacity=.16;b.group.children.find(c=>c.isPointLight).color.set(0x73ffe0);b.group.children.find(c=>c.isPointLight).intensity=4;burst(b.group.position.x,b.group.position.y+2,b.group.position.z,0x9effe5,40);energy=Math.min(100,energy+25);award(100);updateBars();let n=beacons.filter(x=>x.active).length;toast(n<3?`MARCO DESPERTO — ${3-n} restantes`:'TODOS OS MARCOS DESPERTOS — algo se aproxima...');if(n===3)setTimeout(spawnBoss,1800)}
